# Code generated by Claude
"""
Measurement only: peak jerk at the phase boundaries and inside the phases, pulses inside a phase, jumps of the commanded targets, from the series that
experiments/left_arm_motion_measure.py saved.

    python experiments/left_arm_motion_report.py DATA_DIR [--compare OTHER_DATA_DIR] [--episode-log LOG]

Reads DATA_DIR/left_arm.npz and phases.json. Writes DATA_DIR/metrics.json, DATA_DIR/metrics.md (the tables) and the plots DATA_DIR/plot_full.png, plot_over.png, plot_up.png (commanded and
actual position, velocity, acceleration and jerk of the seven joints, every phase boundary marked by a dashed line). With --compare it also writes the per-phase speed and jerk
side by side with the other run (DATA_DIR/compare.md). Uses numpy, scipy and matplotlib only; it loads no simulation.

Definitions. The actual velocity is the simulator's qvel; acceleration and jerk are finite differences of it, at the control tick (150 Hz, the series sampled at the end of
each tick) and at the physics step (750 Hz, noisier). The commanded position is the position actuators' ctrl (what the replay reads). Jerk of a time sample is the largest absolute
value over the seven joints. A boundary window is +-0.5 s around the first tick of a phase; the middle of a phase is its middle half (the first and last quarter left out).
"""

import argparse
import json
import re
import sys
from pathlib import Path

import numpy as np
from scipy.signal import find_peaks

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402

HZ_TICK = 150.0
HZ_STEP = 750.0


def load(d):
    z = np.load(Path(d) / "left_arm.npz")
    ph = json.loads((Path(d) / "phases.json").read_text())
    spt = int(z["steps_per_tick"])
    n = len(z["t"]) // spt * spt
    return {"t": z["t"][:n], "cmd": z["cmd"][:n], "q": z["q"][:n], "qd": z["qd"][:n], "spt": spt, "phases": ph}


def derive(D):
    """Series at the tick rate (end of each tick) and at the step rate: position, velocity, acceleration, jerk of the actual motion and of the commanded position."""
    spt = D["spt"]
    out = {}
    for name, sl, hz in (("tick", slice(spt - 1, None, spt), HZ_TICK), ("step", slice(None), HZ_STEP)):
        t, c, q, v = D["t"][sl], D["cmd"][sl], D["q"][sl], D["qd"][sl]
        a = np.diff(v, axis=0) * hz
        j = np.diff(a, axis=0) * hz
        cv = np.diff(c, axis=0) * hz
        ca = np.diff(cv, axis=0) * hz
        cj = np.diff(ca, axis=0) * hz
        out[name] = {"t": t, "cmd": c, "q": q, "v": v, "a": a, "j": j, "cv": cv, "ca": ca, "cj": cj, "hz": hz}
    return out


def peak_in(t_series, x, lo, hi):
    """Largest absolute value over joints within the time window [lo, hi) of a series whose samples are at times t_series (same length)."""
    m = (t_series >= lo) & (t_series < hi)
    return float(np.max(np.abs(x[m]))) if m.any() else float("nan")


def main(args):
    d = Path(args.data)
    D = load(d)
    S = derive(D)
    spt = D["spt"]
    tick_t = S["tick"]["t"]
    runs = D["phases"]
    # phase intervals in time (a run of equal labels; start tick to end tick)
    def tt(tick):
        i = min(tick * spt, len(D["t"]) - 1)
        return float(D["t"][i])
    phases = [{"key": r["key"], "t0": tt(r["tick"]), "t1": tt(r["end_tick"]) if r["end_tick"] * spt < len(D["t"]) else float(D["t"][-1]), "tick": r["tick"]} for r in runs]
    m = {"phases": [], "boundaries": []}
    # series aligned to times: velocity-derived at tick: a[k] is at tick_t[k+1], j[k] at tick_t[k+2]
    tk = S["tick"]
    ta, tj = tk["t"][1:], tk["t"][2:]
    ts = S["step"]
    tsa, tsj = ts["t"][1:], ts["t"][2:]
    tcv, tcj = tk["t"][1:], tk["t"][3:]
    speed_a = np.linalg.norm(tk["v"], axis=1)
    speed_c = np.linalg.norm(tk["cv"], axis=1)
    for p in phases:
        lo, hi = p["t0"], p["t1"]
        mid_lo, mid_hi = lo + 0.25 * (hi - lo), hi - 0.25 * (hi - lo)
        row = {"key": p["key"], "t0": lo, "t1": hi, "duration": hi - lo,
               "peak_speed_joint": peak_in(tk["t"], tk["v"], lo, hi), "mean_speed_norm": float(np.mean(speed_a[(tk["t"] >= lo) & (tk["t"] < hi)])) if hi > lo else float("nan"),
               "peak_jerk_tick_mid": peak_in(tj, tk["j"], mid_lo, mid_hi), "peak_jerk_tick_all": peak_in(tj, tk["j"], lo, hi),
               "peak_jerk_step_mid": peak_in(tsj, ts["j"], mid_lo, mid_hi), "peak_jerk_step_all": peak_in(tsj, ts["j"], lo, hi),
               "cmd_peak_jerk_tick_mid": peak_in(tk["t"][3:], tk["cj"], mid_lo, mid_hi), "cmd_peak_jerk_tick_all": peak_in(tk["t"][3:], tk["cj"], lo, hi),
               "cmd_peak_speed_joint": peak_in(tk["t"][1:], tk["cv"], lo, hi)}
        m["phases"].append(row)
    for i, p in enumerate(phases):
        if i == 0:
            continue
        b = p["t0"]
        w0, w1 = b - 0.5, b + 0.5
        k = int(np.searchsorted(tk["t"], b))
        cmd_jump = float(np.max(np.abs(tk["cmd"][k] - tk["cmd"][k - 1]))) if 0 < k < len(tk["cmd"]) else float("nan")
        typical = float(np.median(np.max(np.abs(np.diff(tk["cmd"][max(0, k - 150):k + 150], axis=0)), axis=1)))
        pre = (tk["t"] >= b - 0.1) & (tk["t"] < b)
        post = (tk["t"] >= b) & (tk["t"] < b + 0.1)
        m["boundaries"].append({"from": phases[i - 1]["key"], "to": p["key"], "t": b,
                                "peak_jerk_tick_window": peak_in(tj, tk["j"], w0, w1), "peak_jerk_step_window": peak_in(tsj, ts["j"], w0, w1),
                                "cmd_peak_jerk_tick_window": peak_in(tk["t"][3:], tk["cj"], w0, w1),
                                "cmd_jump_one_tick_rad": cmd_jump, "cmd_typical_tick_step_rad": typical,
                                "actual_speed_before_rad_s": float(np.max(np.abs(tk["v"][pre]))) if pre.any() else float("nan"),
                                "actual_speed_after_rad_s": float(np.max(np.abs(tk["v"][post]))) if post.any() else float("nan"),
                                "cmd_speed_before_rad_s": float(np.max(np.abs(np.diff(tk["cmd"][pre], axis=0)))) * HZ_TICK if pre.sum() > 1 else float("nan"),
                                "cmd_speed_after_rad_s": float(np.max(np.abs(np.diff(tk["cmd"][post], axis=0)))) * HZ_TICK if post.sum() > 1 else float("nan")})
    # pulses inside the move phases: local maxima of the speed norm (actual and commanded), at least 15 % of the phase peak, 0.15 s apart
    m["pulses"] = []
    for p in phases:
        if not re.search(r"(PICK|PLACE): (OVER|DOWN|IN|UP|BACK|HOME)", p["key"]):
            continue
        sel_a = (tk["t"] >= p["t0"]) & (tk["t"] < p["t1"])
        sel_c = (tk["t"][1:] >= p["t0"]) & (tk["t"][1:] < p["t1"])
        row = {"key": p["key"], "t0": p["t0"], "t1": p["t1"]}
        for name, x in (("actual", speed_a[sel_a]), ("commanded", speed_c[sel_c])):
            if len(x) < 10:
                row[name] = None
                continue
            xs = np.convolve(x, np.ones(5) / 5, mode="same")
            pk, _ = find_peaks(xs, height=0.15 * xs.max(), distance=int(0.15 * HZ_TICK), prominence=0.05 * xs.max())
            row[name] = {"n_peaks": int(len(pk)), "peak_times": [float(p["t0"] + i / HZ_TICK) for i in pk], "peak_values": [float(xs[i]) for i in pk], "max_speed_norm": float(xs.max())}
        # saturation of the solver's joint speed limit (0.5 rad/s, MINK_CFG max_joint_speed): fraction of ticks where any commanded joint speed is at least 0.49
        cv = np.abs(tk["cv"][sel_c])
        sat = cv >= 0.49                                             # which joints are at the solver's speed limit, per tick
        chg = np.nonzero(np.any(sat[1:] != sat[:-1], axis=1))[0] + 1
        row["saturation_set_changes"] = int(len(chg))
        row["saturation_change_times"] = [round(float(p["t0"] + 1 + i / HZ_TICK), 2) for i in chg[:12]]
        row["saturated_joints"] = sorted({int(k) + 1 for k in np.nonzero(sat.any(axis=0))[0]})
        row["frac_ticks_cmd_joint_speed_ge_0.49"] = float(np.mean(cv.max(axis=1) >= 0.49)) if len(cv) else None
        # dominant frequencies of the actual joint velocity (the video samples at 30 Hz, so content above 15 Hz would alias)
        vs = ts["v"][(ts["t"] >= p["t0"]) & (ts["t"] < p["t1"])]
        if len(vs) > 200:
            f = np.fft.rfftfreq(len(vs), 1 / HZ_STEP)
            P = np.abs(np.fft.rfft(vs - vs.mean(axis=0), axis=0)).sum(axis=1)
            band = (f >= 1.0)
            top = np.argsort(P[band])[::-1][:3]
            row["dominant_freq_hz_above_1hz"] = [float(f[band][i]) for i in top]
            row["power_frac_above_15hz"] = float(P[f >= 15].sum() / max(P[f >= 1].sum(), 1e-12))
        m["pulses"].append(row)
    (d / "metrics.json").write_text(json.dumps(m, indent=1))
    lines = ["# Left arm motion measurement", "", f"Data: {d}", "", "## Per phase (jerk in rad/s^3, speed in rad/s)", "",
             "| phase | t0 | dur s | peak joint speed | mean speed norm | peak jerk mid (150 Hz) | peak jerk all (150 Hz) | peak jerk mid (750 Hz) | cmd peak jerk mid (150 Hz) |", "|---|---|---|---|---|---|---|---|---|"]
    for r in m["phases"]:
        lines.append(f"| {r['key']} | {r['t0']:.2f} | {r['duration']:.2f} | {r['peak_speed_joint']:.3f} | {r['mean_speed_norm']:.3f} | {r['peak_jerk_tick_mid']:.1f} | {r['peak_jerk_tick_all']:.1f} | {r['peak_jerk_step_mid']:.0f} | {r['cmd_peak_jerk_tick_mid']:.1f} |")
    lines += ["", "## Boundaries (window +-0.5 s)", "", "| from -> to | t | peak jerk 150 Hz | peak jerk 750 Hz | cmd peak jerk 150 Hz | cmd jump in one tick (rad) | typical tick step (rad) | actual speed before / after | cmd speed before / after |", "|---|---|---|---|---|---|---|---|---|"]
    for b in m["boundaries"]:
        lines.append(f"| {b['from']} -> {b['to']} | {b['t']:.2f} | {b['peak_jerk_tick_window']:.1f} | {b['peak_jerk_step_window']:.0f} | {b['cmd_peak_jerk_tick_window']:.1f} | {b['cmd_jump_one_tick_rad']:.4f} | {b['cmd_typical_tick_step_rad']:.4f} | {b['actual_speed_before_rad_s']:.3f} / {b['actual_speed_after_rad_s']:.3f} | {b['cmd_speed_before_rad_s']:.3f} / {b['cmd_speed_after_rad_s']:.3f} |")
    lines += ["", "## Pulses inside the move phases (speed-norm peaks, 5-tick smoothed)", ""]
    for r in m["pulses"]:
        a, c = r.get("actual"), r.get("commanded")
        lines.append(f"- {r['key']} ({r['t0']:.2f}-{r['t1']:.2f} s): actual peaks {a['n_peaks'] if a else '-'} at {[round(x, 2) for x in a['peak_times']] if a else '-'}; commanded peaks {c['n_peaks'] if c else '-'} at {[round(x, 2) for x in c['peak_times']] if c else '-'}; cmd joint speed >= 0.49 rad/s on {100 * (r['frac_ticks_cmd_joint_speed_ge_0.49'] or 0):.0f} % of ticks; dominant freq {r.get('dominant_freq_hz_above_1hz')} Hz, power above 15 Hz {100 * r.get('power_frac_above_15hz', float('nan')):.0f} %; joints at the limit {r['saturated_joints']}, set changes {r['saturation_set_changes']} at {r['saturation_change_times']}")
    (d / "metrics.md").write_text("\n".join(lines) + "\n")

    # plots
    def plot(t_lo, t_hi, name):
        fig, ax = plt.subplots(5, 1, figsize=(15, 13), sharex=True)
        sel = lambda t: (t >= t_lo) & (t <= t_hi)
        cols = plt.cm.tab10(np.arange(7))
        for k in range(7):
            ax[0].plot(tk["t"][sel(tk["t"])], tk["q"][sel(tk["t"]), k], color=cols[k], lw=1, label=f"joint {k + 1}")
            ax[0].plot(tk["t"][sel(tk["t"])], tk["cmd"][sel(tk["t"]), k], color=cols[k], lw=0.8, ls=":")
            ax[1].plot(tk["t"][sel(tk["t"])], tk["v"][sel(tk["t"]), k], color=cols[k], lw=1)
            ax[1].plot(tk["t"][1:][sel(tk["t"][1:])], tk["cv"][sel(tk["t"][1:]), k], color=cols[k], lw=0.6, ls=":")
            ax[2].plot(ta[sel(ta)], tk["a"][sel(ta), k], color=cols[k], lw=1)
            ax[3].plot(tj[sel(tj)], tk["j"][sel(tj), k], color=cols[k], lw=1)
            ax[4].plot(tsj[sel(tsj)], ts["j"][sel(tsj), k], color=cols[k], lw=0.5)
        for a_, lab in zip(ax, ["position rad (solid actual, dotted commanded)", "velocity rad/s (dotted: commanded)", "acceleration rad/s^2 (150 Hz)", "jerk rad/s^3 (150 Hz)", "jerk rad/s^3 (750 Hz, raw)"]):
            a_.set_ylabel(lab, fontsize=8)
            for p in phases:
                if t_lo <= p["t0"] <= t_hi:
                    a_.axvline(p["t0"], color="k", ls="--", lw=0.6)
        for p in phases:
            if t_lo <= p["t0"] <= t_hi:
                ax[0].text(p["t0"], ax[0].get_ylim()[1], " " + re.sub(r"^\d/\d ", "", p["key"]), rotation=90, va="top", fontsize=7)
        ax[0].legend(ncol=7, fontsize=7, loc="lower left")
        ax[-1].set_xlabel("sim time s")
        fig.suptitle(f"left arm, {d.name}: {t_lo:.0f}-{t_hi:.0f} s (dashed lines: phase boundaries)")
        fig.tight_layout()
        fig.savefig(d / name, dpi=80)
        plt.close(fig)

    plot(float(D["t"][0]), float(D["t"][-1]), "plot_full.png")
    t_over = next(p["t0"] for p in phases if "PICK: OVER" in p["key"])                # the windows follow the run (a slower ARMS phase moves everything later)
    t_up = next(p["t0"] for p in phases if "PICK: UP" in p["key"])
    plot(t_over - 2.5, t_over + 5.0, "plot_over.png")
    plot(t_up - 2.0, t_up + 4.5, "plot_up.png")
    if args.compare:
        o = Path(args.compare)
        mo = json.loads((o / "metrics.json").read_text())
        L = [f"# Comparison: {d.name} vs {o.name}", "", "| phase | dur (this) | dur (other) | peak joint speed this / other | mean speed norm this / other | peak jerk mid 150 Hz this / other |", "|---|---|---|---|---|---|"]
        key = lambda s: re.sub(r"^\d/\d ", "", s)
        other = {key(r["key"]): r for r in mo["phases"]}
        for r in m["phases"]:
            q = other.get(key(r["key"]))
            if q:
                L.append(f"| {key(r['key'])} | {r['duration']:.2f} | {q['duration']:.2f} | {r['peak_speed_joint']:.3f} / {q['peak_speed_joint']:.3f} | {r['mean_speed_norm']:.3f} / {q['mean_speed_norm']:.3f} | {r['peak_jerk_tick_mid']:.1f} / {q['peak_jerk_tick_mid']:.1f} |")
        L += ["", "| boundary | peak jerk 150 Hz this / other | cmd jump this / other (rad) |", "|---|---|---|"]
        ob = {key(b["to"]): b for b in mo["boundaries"]}
        for b in m["boundaries"]:
            q = ob.get(key(b["to"]))
            if q:
                L.append(f"| -> {key(b['to'])} | {b['peak_jerk_tick_window']:.1f} / {q['peak_jerk_tick_window']:.1f} | {b['cmd_jump_one_tick_rad']:.4f} / {q['cmd_jump_one_tick_rad']:.4f} |")
        (d / "compare.md").write_text("\n".join(L) + "\n")
    print("wrote", d / "metrics.md")
    return 0


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("data")
    ap.add_argument("--compare")
    ap.add_argument("--episode-log")
    sys.exit(main(ap.parse_args()))
